def build_context_pack(self, pack_type: str, target: str | None = None) -> dict[str, Any]:
        from cogz.context import ContextPackEngine

        engine = ContextPackEngine(
            self.state.graph,
            self.state.knowledge,
            self.state.execution,
            self.state.learning,
        )
        if pack_type == "repository":
            pack = engine.build_repository_context(target)
        elif pack_type == "task":
            pack = engine.build_task_context(target or "")
        elif pack_type == "file":
            pack = engine.build_file_context(target or "")
        elif pack_type == "architecture":
            pack = engine.build_architecture_context(target)
        else:
            raise ValueError(f"Unknown pack type: {pack_type}")
