def _build_structured_context_pack(
    engine: ContextPackEngine,
    pack_type: str,
    target: str | None,
    project: str | None,
    subcategory: str | None,
    domain: str | None,
) -> str:
    """Build a structured (non-query) context pack and return as JSON string."""
    if pack_type == "repository":
        pack = engine.build_repository_context(target, project=project, subcategory=subcategory, domain=domain)
    elif pack_type == "task":
        pack = engine.build_task_context(target or "", project=project, subcategory=subcategory, domain=domain)
    elif pack_type == "file":
        pack = engine.build_file_context(target or "", project=project, subcategory=subcategory, domain=domain)
    elif pack_type == "architecture":
        pack = engine.build_architecture_context(target, project=project, subcategory=subcategory, domain=domain)
    else:
        return json.dumps({"error": f"Unknown pack_type: {pack_type}"}, indent=2)
    return json.dumps(pack.to_dict(), indent=2, default=str)

