def evict_for_memory(self, min_free_mb: int) -> int:
        """Evict unused entries (refcount=0) to free memory.

        Called before loading a new model when memory is low. Evicts
        all refcount=0 entries regardless of TTL — freeing memory is
        more important than keeping idle models cached.

        Returns the number of entries evicted.
        """
        avail = _available_mb()
        if avail is None:
            return 0  # Can't check memory on this platform

        if avail >= min_free_mb:
            return 0  # Enough memory, no eviction needed

        to_remove = [
            name for name, entry in self._entries.items()
            if entry.refcount == 0
        ]
        for name in to_remove:
            del self._entries[name]
            logger.info(
                f"{self._name} cache: evicted '{name}' for memory pressure "
                f"({avail:.0f}MB available, {min_free_mb}MB required)"
            )
        return len(to_remove)

