        self,
        max_retries: int,
        wall_budget: float,
    ) -> Any:
        """Build a tenacity retry decorator with project-specific config.

        Uses exponential backoff with max delay cap and wall-budget stop.
        """
        from tenacity.stop import stop_base

        class _WallBudgetStop(stop_base):
            """Stop when wall-clock budget is exceeded."""
            def __init__(self, budget: float, start: float):
                self._budget = budget
                self._start = start
            def __call__(self, retry_state: RetryCallState) -> bool:
                if time.monotonic() - self._start >= self._budget:
                    return True
                return retry_state.attempt_number >= max_retries + 1

        start = time.monotonic()
        return retry(
            stop=_WallBudgetStop(wall_budget, start),
            wait=wait_exponential(
                multiplier=LLM_RETRY_BASE_DELAY,
                max=LLM_RETRY_MAX_DELAY,
            ),
            retry=retry_if_exception_type(RetryableLLMError),
            reraise=True,
