def _detect_ram_mb(self) -> int:
        """Detect total system RAM in MB."""
        try:
            if platform.system() == "Linux":
                with open("/proc/meminfo") as f:
                    match = next((line for line in f if line.startswith("MemTotal:")), None)
                    if match:
                        return int(match.split()[1]) // 1024
            if platform.system() == "Darwin":
                result = subprocess.run(
                    ["sysctl", "-n", "hw.memsize"],
                    capture_output=True, text=True, timeout=5,
                )
                return int(result.stdout.strip()) // (1024 * 1024)
            if platform.system() == "Windows":
                return self._detect_ram_mb_windows()
        except Exception as exc:
            logger.debug(f"RAM detection outer failure: {exc}")
        return 0

